const c: Record<string, string> = {
  "rc.uji.intro": "Uji, juste au sud de la ville de Kyoto, est largement considérée comme le berceau traditionnel du matcha et du gyokuro japonais, et abrite beaucoup des plus anciennes maisons de thé du pays. C'est aussi l'origine déclarée pour le plus grand nombre de produits de cette base de données.",
  "rc.kyoto.intro": "Les produits listés ici viennent des maisons de thé et des producteurs de la préfecture de Kyoto, qui comprend Uji mais aussi d'autres zones de culture du thé.",
  "rc.kyoto.note": "Les marques de cette rubrique n'ont indiqué que « Kyoto », sans ville précise ; nous l'affichons donc comme un groupe à part plutôt que de deviner un lieu plus précis.",
  "rc.shizuoka.intro": "La préfecture de Shizuoka est, avec Kagoshima, l'une des deux plus grandes régions de culture du thé du Japon, surtout connue pour le sencha. Son matcha est moins associé à la tradition cérémonielle que celui d'Uji, et les prix de cette base de données le reflètent.",
  "rc.shizuoka.note": "Les marques de cette rubrique n'ont indiqué que « Shizuoka », sans ville précise.",
  "rc.kagoshima.intro": "Kagoshima, à l'extrémité sud de Kyushu, est l'une des plus grandes préfectures productrices de thé du Japon. Son climat chaud du sud se prête à une production à grande échelle, et la préfecture est réputée pour son thé bio.",
  "rc.nishio.intro": "Nishio, dans la préfecture d'Aichi, est une grande zone de production de matcha et le siège de gros producteurs comme Aiya et Aoi Tea, qui fournissent du matcha en gros aux marques et aux fabricants.",
  "rc.yame.intro": "Yame, dans la préfecture de Fukuoka (Kyushu), est surtout connue pour ses thés cultivés à l'ombre comme le gyokuro, et est devenue une source de matcha cérémoniel vendu par des producteurs japonais comme par des importateurs occidentaux.",
  "rc.wazuka.intro": "Wazuka est une ville de montagne du sud de la préfecture de Kyoto, au sud-est d'Uji, et une zone de culture du thé réputée, avec des théiers plantés sur des pentes abruptes.",
  "rc.shirakawa.intro": "Shirakawa est un district de culture du thé situé dans Uji. Ce n'est pas une commune distincte : sur la carte, il partage donc la limite d'Uji.",
  "rc.china.intro": "Ces produits n'indiquent que « Chine » comme origine, sans province, région ni ferme. Le pays étant très vaste, une origine au niveau national en dit peu sur la façon et le lieu où le thé a été cultivé.",
  "cvc.yabukita.title": "Matcha Yabukita : le cultivar de thé le plus répandu au Japon",
  "cvc.yabukita.desc": "Ce qu'est le cultivar de thé Yabukita, comment on le décrit et comment le matcha qui en est issu se compare en prix, qualité et région de culture selon les marques.",
  "cvc.yabukita.intro.0": "Le Yabukita est le cultivar de thé le plus planté au Japon. Il a été sélectionné en 1908 par Hikosaburo Sugiyama à Shizuoka et enregistré en 1953, et représente encore la plus grande part des plantations de thé du pays : environ 60 à 75 %, selon l'année et la source.",
  "cvc.yabukita.intro.1": "La plupart du Yabukita sert au sencha quotidien, mais il est aussi utilisé pour le matcha. On le décrit généralement comme frais, légèrement herbacé et doucement sucré, avec une astringence légère, ainsi que robuste et adaptable, ce qui explique en partie sa grande diffusion.",
  "cvc.yabukita.p0": "Sélection :: 1908, Shizuoka, par Hikosaburo Sugiyama",
  "cvc.yabukita.p1": "Enregistrement :: 1953",
  "cvc.yabukita.p2": "Part des plantations de thé du Japon :: Environ 60 à 75 %, selon l'année et la source",
  "cvc.yabukita.p3": "Description habituelle :: Frais, légèrement herbacé, doucement sucré, astringence légère",
  "cvc.okumidori.desc": "Ce qu'est le cultivar de thé Okumidori, comment on le décrit et comment le matcha qui en est issu se compare en prix, qualité et région de culture selon les marques.",
  "cvc.okumidori.intro.0": "L'Okumidori est un cultivar à débourrement tardif très utilisé pour le matcha et le gyokuro. « Tardif » signifie que ses pousses de printemps s'ouvrent plus tard que celles du Yabukita : il est donc récolté plus tard dans la saison.",
  "cvc.okumidori.intro.1": "Producteurs et vendeurs le décrivent couramment comme riche en umami, d'un vert profond et peu amer, et disent qu'il supporte bien l'ombrage. Voyez-y des descriptions plutôt que des mesures : le goût d'un matcha dépend autant de l'ombrage, de la récolte et de la mouture que du cultivar.",
  "cvc.okumidori.p0": "Débourrement :: Tardif, après le Yabukita",
  "cvc.okumidori.p1": "Usages courants :: Matcha (tencha) et gyokuro",
  "cvc.okumidori.p2": "Description habituelle :: Riche en umami, vert profond, peu d'amertume",
  "cvc.samidori.desc": "Ce qu'est le cultivar de thé Samidori, en quoi il diffère du Saemidori et comment le matcha qui en est issu se compare en prix, qualité et région de culture.",
  "cvc.samidori.intro.0": "Le Samidori est l'une des « variétés d'Uji » : un cultivar sélectionné dans les années 1950 à partir des théiers autochtones d'Uji et cultivé surtout pour les thés ombragés, le tencha (la feuille qui devient du matcha) et le gyokuro. Il n'est pas enregistré au niveau national. On le confond facilement avec le Saemidori, un autre cultivar au nom proche.",
  "cvc.samidori.intro.1": "Les vendeurs décrivent couramment le Samidori comme équilibré, sucré et crémeux, avec une faible astringence.",
  "cvc.samidori.p0": "Origine :: Sélectionné à partir de théiers autochtones d'Uji, années 1950",
  "cvc.samidori.p1": "Enregistrement :: Non enregistré au niveau national",
  "cvc.samidori.p2": "Usages courants :: Tencha (matcha) et gyokuro",
  "cvc.samidori.p3": "Description habituelle :: Équilibré, sucré, crémeux, faible astringence",
  "cvc.saemidori.desc": "Ce qu'est le cultivar de thé Saemidori, en quoi il diffère du Samidori et comment le matcha qui en est issu se compare en prix, qualité et région de culture.",
  "cvc.saemidori.intro.0": "Le Saemidori a été obtenu à Kagoshima et enregistré en 1990. C'est un cultivar à débourrement précoce, récolté avant le Yabukita, apprécié pour le matcha grâce à son vert éclatant et sa douceur naturelle. C'est un cultivar différent du Samidori.",
  "cvc.saemidori.intro.1": "On le décrit généralement comme sucré, rond et peu amer. Comme il a été conçu pour les climats du sud autant que pour celui de Kyoto, le matcha qui en est issu provient d'un éventail de régions plus large que celui des variétés d'Uji.",
  "cvc.saemidori.p0": "Obtention :: Kagoshima, enregistré en 1990",
  "cvc.saemidori.p1": "Débourrement :: Précoce, avant le Yabukita",
  "cvc.saemidori.p2": "Description habituelle :: Sucré, rond, peu amer, vert éclatant",
  "cvc.asahi.title": "Matcha Asahi : le cultivar prisé d'Uji, prix et origines",
  "cvc.asahi.desc": "Ce qu'est le cultivar de thé Asahi, pourquoi il est prisé à Uji et comment le matcha qui en est issu se compare en prix, qualité et région de culture selon les marques.",
  "cvc.asahi.intro.0": "L'Asahi est un cultivar traditionnel d'Uji, sélectionné en 1954 parmi les théiers autochtones d'Uji par un agriculteur, Hirano Jinnojō. C'est l'une des trois « variétés d'Uji » avec le Samidori et l'Ujihikari ; il n'est pas enregistré au niveau national et est cultivé presque exclusivement pour le tencha et le gyokuro. On le dit exigeant : la période de cueillette est étroite.",
  "cvc.asahi.intro.1": "Plusieurs sources le décrivent comme l'un des cultivars de tencha les plus chers, à l'umami concentré, sucré et peu amer, et comme un incontournable du matcha de concours. Nos données de prix ci-dessous montrent si cela se vérifie parmi les marques de la base.",
  "cvc.asahi.p0": "Sélection :: 1954, Uji, par Hirano Jinnojō",
  "cvc.asahi.p1": "Enregistrement :: Non enregistré au niveau national",
  "cvc.asahi.p2": "Usages courants :: Tencha (matcha) ; rarement le gyokuro",
  "cvc.asahi.p3": "Description habituelle :: Umami et douceur riches, peu d'amertume",
  "cvc.gokou.title": "Matcha Gokou (Gokō) : profil du cultivar, prix et origines",
  "cvc.gokou.desc": "Ce qu'est le cultivar de thé Gokou (Gokō), comment on décrit son arôme et comment le matcha qui en est issu se compare en prix, qualité et région de culture.",
  "cvc.gokou.intro.0": "Le Gokou, aussi écrit Gokō, est un cultivar de Kyoto sélectionné au début des années 1950, à peu près en même temps que le Samidori et l'Asahi, et cultivé surtout sur de petites parcelles pour les thés ombragés et le matcha. Il est connu pour son arôme, que les vendeurs décrivent comme crémeux, chocolaté ou évoquant le lait vapeur.",
  "cvc.gokou.intro.1": "Délicat, il est généralement cultivé en petites quantités et apparaît souvent dans les matchas destinés aux concours.",
  "cvc.gokou.p0": "Origine :: Kyoto, sélectionné au début des années 1950",
  "cvc.gokou.p1": "Usages courants :: Tencha (matcha), thés ombragés",
  "cvc.gokou.p2": "Description habituelle :: Aromatique : notes crémeuses, chocolatées, de lait vapeur",
  "cvc.tsuyuhikari.desc": "Où les marques disent que le matcha Tsuyuhikari est cultivé, ainsi que le prix, la qualité et les notes de saveur des matchas citant le cultivar Tsuyuhikari.",
  "cvc.tsuyuhikari.intro.0": "Les marques citent le Tsuyuhikari sur plusieurs produits matcha, cultivés dans plus d'une région. Il a été moins publié en anglais sur lui que sur le Yabukita ou les variétés d'Uji ; cette page s'appuie donc sur ce que les marques déclarent elles-mêmes plutôt que sur des affirmations de contexte que nous n'avons pas pu vérifier.",
  "cvc.tsuyuhikari.intro.1": "Les tableaux ci-dessous montrent où ce matcha est cultivé, comment les marques le classent et quel goût elles lui attribuent.",
  "rt.l-theanine-and-caffeine.heading": "Matcha, L-théanine et caféine : la recherche",
  "rt.l-theanine-and-caffeine.title": "Recherche sur la L-théanine et la caféine du matcha — bibliothèque d'études",
  "rt.l-theanine-and-caffeine.desc": "Études évaluées par des pairs sur la teneur du matcha en L-théanine et en caféine, leur interaction, et ce que rapportent les essais sur l'attention, la vigilance et le calme.",
  "rt.l-theanine-and-caffeine.intro.0": "Le matcha est cultivé à l'ombre, ce qui augmente sa L-théanine, un acide aminé presque exclusivement présent dans le thé, et il se consomme sous forme de feuille entière moulue : il apporte donc aussi de la caféine. Une bonne part de la littérature sur le matcha étudie comment ces deux composés se comportent ensemble.",
  "rt.l-theanine-and-caffeine.intro.1": "Les études comprennent des analyses chimiques de la teneur de chaque qualité de matcha en chaque composé, des essais chez l'humain de combinaisons théanine-caféine sur l'attention et l'humeur, et des travaux de culture sur la façon dont l'ombrage modifie les niveaux de théanine.",
  "rt.l-theanine-and-caffeine.look": "Les essais testent souvent de la L-théanine et de la caféine purifiées plutôt que le matcha lui-même : vérifiez ce qui a réellement été administré avant d'appliquer un résultat à une tasse de matcha.",
  "rt.cognition-mood-and-stress.heading": "Matcha, cognition, humeur et stress : la recherche",
  "rt.cognition-mood-and-stress.title": "Matcha, concentration, humeur et stress : ce qu'examinent les études",
  "rt.cognition-mood-and-stress.desc": "Essais cliniques, études observationnelles et revues sur le matcha et le thé vert pour l'attention, la mémoire, l'humeur, le stress et le sommeil, avec des liens vers toutes les sources.",
  "rt.cognition-mood-and-stress.intro.0": "C'est le volet de la recherche sur le matcha qui concerne l'humain : essais randomisés et études observationnelles qui mesurent l'attention, la mémoire, l'humeur, les hormones du stress ou le sommeil après que des personnes ont bu du matcha, pris des extraits ou mangé des aliments au matcha.",
  "rt.cognition-mood-and-stress.intro.1": "Les échantillons sont souvent petits et beaucoup d'études sont courtes ; les revues qui regroupent plusieurs essais sont donc un bon point de départ avant de lire les articles individuels.",
  "rt.cognition-mood-and-stress.look": "Regardez d'abord l'étiquette du type d'étude. Un essai contrôlé randomisé ou une revue systématique pèse plus qu'une seule étude observationnelle ou qu'une expérience en laboratoire.",
  "rt.antioxidants-and-polyphenols.heading": "Antioxydants, catéchines et EGCG du matcha : la recherche",
  "rt.antioxidants-and-polyphenols.title": "Antioxydants, catéchines et EGCG du matcha — bibliothèque de recherche",
  "rt.antioxidants-and-polyphenols.desc": "Études mesurant les catéchines, l'EGCG, la chlorophylle et d'autres polyphénols du matcha, leur variabilité et leur tenue à la transformation et au stockage.",
  "rt.antioxidants-and-polyphenols.intro.0": "Comme la feuille entière est consommée, le matcha est riche en catéchines (surtout l'EGCG), en chlorophylle et en autres polyphénols. C'est le plus grand thème de la bibliothèque, entre chimie analytique, science des aliments et études cellulaires et animales de l'activité antioxydante.",
  "rt.antioxidants-and-polyphenols.intro.1": "De nombreux articles comparent le matcha au thé vert infusé ordinaire, mesurent la dégradation des catéchines par le stockage, la lumière et la température, ou testent des aliments enrichis en matcha.",
  "rt.antioxidants-and-polyphenols.look": "Les tests antioxydants de laboratoire mesurent la chimie d'un composé dans une boîte. Ils ne démontrent pas à eux seuls un bénéfice chez l'humain.",
  "rt.metabolism-and-weight.heading": "Matcha, métabolisme et poids : la recherche",
  "rt.metabolism-and-weight.title": "Matcha, métabolisme et poids : études sur l'obésité et la glycémie",
  "rt.metabolism-and-weight.desc": "Études chez l'humain, l'animal et sur cellules sur le matcha et le thé vert concernant le poids, le métabolisme des graisses, la glycémie, le cholestérol et la stéatose hépatique.",
  "rt.metabolism-and-weight.intro.0": "Les chercheurs ont étudié l'effet du matcha sur le poids, l'oxydation des graisses, la glycémie, les lipides et la stéatose hépatique, surtout sur des modèles animaux et de petits essais chez l'humain, souvent avec un régime riche en graisses comme contrainte expérimentale.",
  "rt.metabolism-and-weight.intro.1": "Les résultats ne sont pas uniformes d'une étude à l'autre, et la dose, la durée et la forme du matcha varient largement.",
  "rt.metabolism-and-weight.look": "Beaucoup d'études sur le poids sont réalisées chez la souris ou le rat. Consultez l'étiquette du type d'étude pour savoir quels résultats viennent d'humains.",
  "rt.gut-and-microbiome.heading": "Le matcha et le microbiote intestinal : la recherche",
  "rt.gut-and-microbiome.title": "Le matcha et le microbiote intestinal : recherches sur la digestion et le microbiome",
  "rt.gut-and-microbiome.desc": "Études sur l'interaction du matcha et de ses polyphénols avec le microbiote intestinal, la digestion et la santé intestin-foie, des modèles cellulaires aux essais chez l'humain.",
  "rt.gut-and-microbiome.intro.0": "Un nombre croissant d'études se demande comment les polyphénols du matcha sont digérés, lesquels atteignent le côlon et comment ils modifient les bactéries intestinales et les métabolites qu'elles produisent.",
  "rt.gut-and-microbiome.intro.1": "La plupart de ces travaux sont récents et beaucoup portent sur l'animal. Quelques études chez l'humain, dont des articles de protocole d'essais en cours, commencent à paraître.",
  "rt.gut-and-microbiome.look": "Les résultats sur le microbiome chez la souris ne se transposent pas automatiquement à l'humain ; cherchez les études chez l'humain dans le filtre Type d'étude.",
  "rt.inflammation-and-immunity.heading": "Matcha, inflammation et immunité : la recherche",
  "rt.inflammation-and-immunity.title": "Recherches sur le matcha, l'inflammation et l'immunité — bibliothèque d'études",
  "rt.inflammation-and-immunity.desc": "Études sur cellules, animaux et humains sur les effets du matcha sur les marqueurs de l'inflammation et la fonction immunitaire.",
  "rt.inflammation-and-immunity.intro.0": "Ces études examinent les marqueurs inflammatoires, l'activité des cellules immunitaires et les voies associées après administration de matcha ou de composés dérivés à des cellules, des animaux ou des personnes.",
  "rt.inflammation-and-immunity.intro.1": "L'essentiel des preuves est préclinique, c'est-à-dire des travaux de laboratoire et sur l'animal qui suggèrent des mécanismes à tester dans des essais chez l'humain.",
  "rt.inflammation-and-immunity.look": "Considérez les résultats sur cellules et animaux comme des hypothèses. Les essais randomisés chez l'humain sont la preuve la plus solide, et ils sont plus rares ici.",
  "rt.safety-contaminants-and-toxicity.heading": "Sécurité et contaminants du matcha : la recherche",
  "rt.safety-contaminants-and-toxicity.title": "Études sur la sécurité, le fluor, les résidus de pesticides et les contaminants du matcha",
  "rt.safety-contaminants-and-toxicity.desc": "Études publiées testant la présence de fluor, de résidus de pesticides, d'oligo-éléments, de microplastiques et d'autres contaminants dans le matcha et le thé, avec des liens vers toutes les sources.",
  "rt.safety-contaminants-and-toxicity.intro.0": "Le matcha étant la feuille entière en poudre et non une infusion, tout ce qui se trouve dans la feuille finit dans la tasse. Ce thème rassemble les études d'analyse : teneur en fluor, méthodes de dosage des résidus de pesticides, oligo-éléments et minéraux, microplastiques, et détection de solvants industriels dans du matcha du commerce.",
  "rt.safety-contaminants-and-toxicity.intro.1": "C'est un corpus réduit, et il faut dire clairement ce qu'il ne contient pas : cette bibliothèque ne compte aucune étude mesurant le plomb ou d'autres métaux lourds spécifiquement dans le matcha. Les résultats varient aussi selon l'origine, la qualité et les conditions de culture ; lisez donc les détails d'échantillonnage de chaque article.",
  "rt.safety-contaminants-and-toxicity.look": "Vérifiez où et quand les échantillons ont été achetés. Un résultat portant sur un marché ou une année ne décrit pas toutes les marques.",
  "rt.processing-milling-and-quality.heading": "Transformation, mouture et qualité du matcha : la recherche",
  "rt.processing-milling-and-quality.title": "Recherches sur la transformation, la mouture et la qualité du matcha : du tencha à la poudre",
  "rt.processing-milling-and-quality.desc": "Études sur la façon dont le tencha est cuit à la vapeur, séché et moulu à la meule, sur l'effet de la taille des particules et du stockage sur la couleur, la saveur et les nutriments, et sur le classement de la qualité du matcha.",
  "rt.processing-milling-and-quality.intro.0": "La qualité du matcha dépend d'étapes que la plupart des buveurs ne voient jamais : cuire à la vapeur et sécher la feuille cultivée à l'ombre pour obtenir du tencha, la moudre à quelques microns et la stocker. Les spécialistes des aliments ont étudié chaque étape.",
  "rt.processing-milling-and-quality.intro.1": "C'est l'un des plus grands thèmes de la bibliothèque : mouture à la meule contre broyeur à billes, taille des particules, rétention de la chlorophylle, stabilité au stockage et indicateurs de qualité comme la couleur et la teneur en acides aminés.",
  "rt.processing-milling-and-quality.look": "Les articles de ce thème comparent souvent des méthodes sur un même lot de feuilles : ils montrent des effets relatifs, pas ce que fait telle ou telle marque.",
  "rt.cultivation-and-shading.heading": "Culture et ombrage du matcha : la recherche",
  "rt.cultivation-and-shading.title": "Recherches sur la culture du matcha et la culture à l'ombre : études sur le théier",
  "rt.cultivation-and-shading.desc": "Études d'agronomie et de biologie végétale sur la culture du thé à l'ombre pour le matcha : comment l'ombrage modifie la théanine, la chlorophylle, les catéchines et la qualité de la feuille.",
  "rt.cultivation-and-shading.intro.0": "Le caractère du matcha commence au champ, où les théiers sont ombragés plusieurs semaines avant la récolte. Les botanistes ont étudié comment l'ombrage modifie l'expression des gènes, les acides aminés, la chlorophylle et les catéchines de la feuille.",
  "rt.cultivation-and-shading.intro.1": "Les études portent sur la durée et le matériau de l'ombrage, la fertilisation, le choix du cultivar et le moment de la récolte.",
  "rt.cultivation-and-shading.look": "Les articles de biologie végétale peuvent être techniques. Le résumé énonce généralement le résultat pratique dans ses dernières phrases.",
  "rt.aroma-flavor-and-sensory.heading": "Arôme, saveur et science sensorielle du matcha : la recherche",
  "rt.aroma-flavor-and-sensory.title": "Recherches sur la saveur, l'arôme et le goût du matcha : études de science sensorielle",
  "rt.aroma-flavor-and-sensory.desc": "Études des composés aromatiques du matcha, de l'amertume, de l'umami et de l'astringence, et de la façon dont consommateurs et panels entraînés l'évaluent.",
  "rt.aroma-flavor-and-sensory.intro.0": "Les spécialistes de l'analyse sensorielle ont cartographié les composés aromatiques volatils du matcha, l'équilibre entre umami, amertume et astringence, et la façon dont des facteurs comme la qualité, l'origine et le fouettage modifient ce que les gens goûtent.",
  "rt.aroma-flavor-and-sensory.intro.1": "Le thème associe l'analyse instrumentale (chromatographie en phase gazeuse et langues électroniques) à des études de panels entraînés et de préférence des consommateurs.",
  "rt.aroma-flavor-and-sensory.look": "Les résultats sensoriels dépendent du panel et du mode de préparation : vérifiez comment le matcha a été préparé avant de comparer des études.",
  "rt.authenticity-and-analytical-methods.heading": "Authenticité et méthodes d'analyse du matcha : la recherche",
  "rt.authenticity-and-analytical-methods.title": "Authenticité, classement et méthodes d'analyse du matcha — bibliothèque de recherche",
  "rt.authenticity-and-analytical-methods.desc": "Études sur la façon de distinguer le vrai matcha des imitations, de classer la qualité par spectroscopie et chimie, et de détecter les falsifications.",
  "rt.authenticity-and-analytical-methods.intro.0": "À mesure que le matcha est devenu populaire, les analystes ont mis au point des moyens de vérifier ce que contient une boîte : imagerie proche infrarouge et hyperspectrale, fluorescence et autres spectroscopies associées à l'apprentissage automatique pour identifier la qualité, le producteur ou l'origine géographique, et tests ADN pour les adultérants végétaux.",
  "rt.authenticity-and-analytical-methods.intro.1": "C'est l'ossature technique de toute affirmation sur la qualité ou l'origine.",
  "rt.authenticity-and-analytical-methods.look": "Les articles de méthodes montrent ce qui peut être mesuré, pas ce que contient le matcha d'un rayon donné.",
  "rt.food-products-and-applications.heading": "Le matcha dans les aliments : la recherche sur les produits et les applications",
  "rt.food-products-and-applications.title": "Le matcha dans les produits alimentaires — nouilles, pâtisseries, produits laitiers et plus",
  "rt.food-products-and-applications.desc": "Études de science des aliments qui ajoutent du matcha aux nouilles, au pain, aux glaces, aux yaourts, au chocolat et aux boissons, et mesurent l'effet sur la nutrition, la texture et le goût.",
  "rt.food-products-and-applications.intro.0": "Le matcha est utilisé comme ingrédient fonctionnel, et les spécialistes des aliments l'ont testé dans les nouilles, le pain, les biscuits, le yaourt, les glaces, le chocolat et les boissons, en mesurant son effet sur la couleur, la texture, la teneur en antioxydants et l'acceptation des consommateurs.",
  "rt.food-products-and-applications.intro.1": "Plusieurs articles testent aussi l'effet de la cuisson ou du four sur les composés du matcha.",
  "rt.food-products-and-applications.look": "La plupart de ces études relèvent du développement de produits, avec de petits panels et sans critères de santé.",
  "rt.market-culture-and-sustainability.heading": "Marchés, culture et durabilité du matcha : la recherche",
  "rt.market-culture-and-sustainability.title": "Études sur le marché, la culture et la durabilité du matcha — bibliothèque de recherche",
  "rt.market-culture-and-sustainability.desc": "Études du marché du matcha, du comportement des consommateurs, de la culture de la cérémonie du thé, des chaînes d'approvisionnement et de l'empreinte environnementale de la production.",
  "rt.market-culture-and-sustainability.intro.0": "Toute la recherche sur le matcha n'est pas de la science de laboratoire. Ce thème rassemble des articles sur la demande des consommateurs et le marketing, la culture japonaise du thé et la cérémonie, et les questions de durabilité que soulève la croissance rapide du matcha.",
  "rt.market-culture-and-sustainability.intro.1": "Beaucoup sont des études de gestion ou de sciences sociales, et la qualité varie davantage ici que dans la littérature de laboratoire.",
  "rt.market-culture-and-sustainability.look": "Les études de marché sont souvent de petites enquêtes locales. Vérifiez l'échantillon et le lieu avant de tirer des conclusions plus larges.",
  "rt.skin-oral-and-dental.heading": "Le matcha pour la peau, la bouche et les dents : la recherche",
  "rt.skin-oral-and-dental.title": "Recherches sur le matcha, la peau, la santé buccale et dentaire — bibliothèque d'études",
  "rt.skin-oral-and-dental.desc": "Études sur les catéchines du matcha et du thé vert dans les soins de la peau, les bactéries buccales, la santé des gencives et les applications dentaires.",
  "rt.skin-oral-and-dental.intro.0": "Les catéchines agissent contre certaines bactéries buccales et ont été examinées dans des bains de bouche et des produits dentaires, et des extraits de matcha ont été testés sur des modèles de peau pour les effets des UV et du vieillissement.",
  "rt.skin-oral-and-dental.intro.1": "L'essentiel des travaux relève de la recherche en laboratoire, avec un plus petit nombre d'études cliniques.",
  "rt.skin-oral-and-dental.look": "De nombreux résultats utilisent des extraits à des concentrations très éloignées de celles d'une tasse de matcha : lisez les détails de l'exposition.",
  "rt.cancer.heading": "Matcha et recherche sur le cancer",
  "rt.cancer.title": "Matcha et recherche sur le cancer : études sur l'EGCG et les cellules tumorales",
  "rt.cancer.desc": "Études de laboratoire, sur l'animal et épidémiologiques examinant les composés du matcha et du thé vert dans les cellules cancéreuses et le risque de cancer.",
  "rt.cancer.intro.0": "Les chercheurs ont étudié des extraits de matcha et l'EGCG dans des lignées de cellules cancéreuses (buccales, mammaires et autres) et dans des modèles animaux, et plusieurs revues résument l'ensemble des données sur le thé vert.",
  "rt.cancer.intro.1": "L'essentiel des travaux spécifiques au matcha est préclinique. Ces articles décrivent des mécanismes dans des cellules et des animaux, pas des traitements.",
  "rt.cancer.look": "Un résultat sur des cellules cancéreuses en culture est un point de départ pour d'autres recherches, pas la preuve que le matcha prévient ou traite le cancer.",
  "rt.cardiovascular-and-blood-pressure.heading": "Matcha, santé du cœur et tension artérielle : la recherche",
  "rt.cardiovascular-and-blood-pressure.title": "Matcha, santé du cœur et tension artérielle : recherche cardiovasculaire",
  "rt.cardiovascular-and-blood-pressure.desc": "Études sur les catéchines du matcha et du thé vert pour la tension artérielle, le cholestérol, la fonction vasculaire et le tissu cardiaque.",
  "rt.cardiovascular-and-blood-pressure.intro.0": "La recherche cardiovasculaire sur le matcha est modeste comparée à la littérature plus large sur le thé vert. Elle comprend des études animales sur le tissu cardiaque soumis à un stress alimentaire, un court essai chez l'humain sur la variabilité de la fréquence cardiaque, des revues sur le matcha et la santé cardiométabolique, et des travaux de développement de produits visant la tension artérielle.",
  "rt.cardiovascular-and-blood-pressure.look": "Faute d'essais chez l'humain propres au matcha, les résultats de la littérature plus large sur le thé vert sont souvent les meilleures données disponibles.",
  "gd.matcha-for-lattes.title": "Meilleur matcha pour les lattes : comparé par prix et qualité",
  "gd.matcha-for-lattes.h1": "Meilleur matcha pour les lattes",
  "gd.matcha-for-lattes.desc": "Poudres de matcha que les marques vendent pour les lattes, comparées par qualité, origine et prix aux 30 g, d'après la page produit de chaque marque.",
  "gd.matcha-for-lattes.intro.0": "Dans un latte, le matcha passe derrière le lait et, en général, un édulcorant, et l'on utilise plus de poudre par boisson que pour un bol fouetté. Deux choses comptent donc : la saveur tient-elle une fois diluée, et combien coûte chaque gramme.",
  "gd.matcha-for-lattes.intro.1": "Les marques étiquettent différemment les produits pour les lattes. Certaines vendent une qualité dédiée latte ou barista, d'autres recommandent leur qualité culinaire, d'autres encore disent que leur matcha cérémoniel convient aussi. Cette page liste des poudres de matcha nature dont la page produit mentionne les lattes, les boissons glacées ou les smoothies, avec la qualité indiquée par chaque marque. Les mélanges à latte tout prêts sont exclus, ainsi que le matcha vendu en koicha ou usucha, destiné à la préparation traditionnelle.",
  "gd.matcha-for-lattes.list.0.h": "Marques connues avec un matcha adapté aux lattes",
  "gd.matcha-for-lattes.list.0.n": "D'abord un produit par marque, par ordre de notoriété, pour que la liste ne soit pas tout le catalogue d'une seule marque.",
  "gd.matcha-for-lattes.list.1.h": "Prix le plus bas aux 30 g pour les lattes",
  "gd.matcha-for-lattes.list.1.n": "Deux produits au maximum par marque.",
  "gd.matcha-for-lattes.faq.0.q": "Quelle qualité de matcha est la meilleure pour les lattes ?",
  "gd.matcha-for-lattes.faq.0.bits": " Dans ces données, {cn} poudres adaptées aux lattes sont étiquetées cérémonielles (médiane {cm} les 30 g) et {un} culinaires (médiane {um} les 30 g).",
  "gd.matcha-for-lattes.faq.0.a": "Il n'existe pas de norme officielle de qualité : les étiquettes sont propres à chaque marque.{bits} Les qualités culinaire et « barista » coûtent moins cher aux 30 g et sont faites pour être mélangées au lait, tandis que la qualité cérémonielle a un goût plus doux mais coûte plus cher. Beaucoup de gens utilisent l'une ou l'autre.",
  "gd.matcha-for-lattes.faq.1.q": "Quelle quantité de matcha dans un latte ?",
  "gd.matcha-for-lattes.faq.1.a": "Les recettes utilisent couramment 2 à 4 grammes (environ 1 à 2 cuillères à café) par boisson. Au prix médian de {median} les 30 g des poudres de cette page, cela fait environ {lo} à {hi} de matcha par latte.",
  "gd.matcha-for-lattes.faq.2.q": "Cela vaut-il la peine d'utiliser du matcha cérémoniel dans un latte ?",
  "gd.matcha-for-lattes.faq.2.ratio": " Dans ces données, le cérémoniel coûte environ {x} fois plus cher aux 30 g que le culinaire.",
  "gd.matcha-for-lattes.faq.2.a": "C'est une question de goût et de budget. Le lait et l'édulcorant masquent une partie de la nuance qui rend la qualité cérémonielle chère ; beaucoup la réservent donc au thé fouetté à l'eau.{ratio}",
  "gd.ceremonial-vs-culinary-matcha.title": "Matcha cérémoniel vs culinaire : différences et prix",
  "gd.ceremonial-vs-culinary-matcha.h1": "Matcha cérémoniel vs culinaire",
  "gd.ceremonial-vs-culinary-matcha.desc": "Ce que signifient le matcha cérémoniel et le matcha culinaire, en quoi ils diffèrent par le goût et l'usage, et combien chacun coûte aux 30 g selon les marques.",
  "gd.ceremonial-vs-culinary-matcha.intro.0": "Cérémoniel et culinaire sont les deux étiquettes de qualité que l'on voit le plus. Le cérémoniel est vendu pour être bu fouetté à l'eau ; le culinaire pour les lattes, les smoothies et la pâtisserie. Les marques appliquent ces étiquettes elles-mêmes. À notre connaissance, aucune norme légale ou sectorielle ne les encadre : le même mot peut donc recouvrir des qualités différentes selon les vendeurs.",
  "gd.ceremonial-vs-culinary-matcha.intro.1": "Ce qui diffère généralement : le matcha cérémoniel est le plus souvent fait des feuilles les plus jeunes cultivées à l'ombre et tend à être plus sucré et plus onctueux, tandis que le culinaire provient souvent de récoltes plus tardives et a un côté plus fort et plus amer qui tient face au lait et au sucre. Le tableau montre ce que coûte cette différence.",
  "gd.ceremonial-vs-culinary-matcha.list.0.h": "Matcha cérémoniel de marques connues",
  "gd.ceremonial-vs-culinary-matcha.list.1.h": "Matcha culinaire de marques connues",
  "gd.ceremonial-vs-culinary-matcha.faq.0.q": "Quelle est la différence entre le matcha cérémoniel et le matcha culinaire ?",
  "gd.ceremonial-vs-culinary-matcha.faq.0.price": " Dans ces données, la médiane aux 30 g est de {cm} pour le cérémoniel et de {um} pour le culinaire.",
  "gd.ceremonial-vs-culinary-matcha.faq.0.a": "Le cérémoniel est vendu pour être bu à l'eau et est généralement plus doux et plus sucré ; le culinaire est vendu pour les lattes et la cuisine et a un goût plus fort et plus amer.{price}",
  "gd.ceremonial-vs-culinary-matcha.faq.1.q": "L'étiquette de qualité cérémonielle est-elle réglementée ?",
  "gd.ceremonial-vs-culinary-matcha.faq.1.a": "À notre connaissance, non. Ces termes sont des étiquettes marketing fixées par chaque marque, c'est pourquoi ce site enregistre la qualité telle que la marque l'indique et compare le prix aux 30 g plutôt que de se fier à la seule étiquette.",
  "gd.ceremonial-vs-culinary-matcha.faq.2.q": "Puis-je utiliser du matcha cérémoniel en pâtisserie ?",
  "gd.ceremonial-vs-culinary-matcha.faq.2.ratio": " Dans ces données, il coûte environ {x} fois plus cher aux 30 g.",
  "gd.ceremonial-vs-culinary-matcha.faq.2.a": "On peut, mais la chaleur et les autres ingrédients estompent la saveur délicate pour laquelle on paie la qualité cérémonielle ; la plupart des pâtissiers utilisent donc la qualité culinaire.{ratio}",
  "gd.ceremonial-vs-culinary-matcha.faq.3.q": "Puis-je boire du matcha culinaire avec de l'eau ?",
  "gd.ceremonial-vs-culinary-matcha.faq.3.a": "Oui. Attendez-vous à un goût plus fort et plus amer qu'avec une qualité cérémonielle. Le matcha culinaire de certaines marques est agréable seul, mais il est formulé pour être mélangé.",
  "gd.matcha-under-20.title": "Meilleur matcha à moins de 20 $ : prix aux 30 g comparés",
  "gd.matcha-under-20.h1": "Meilleur matcha à moins de 20 $",
  "gd.matcha-under-20.desc": "Poudres de matcha à 20 $ ou moins, comparées par format et prix aux 30 g, avec la qualité et l'origine tirées de la page de chaque marque.",
  "gd.matcha-under-20.intro.0": "Pour moins de 20 $, de nombreux vendeurs proposent une boîte de 20 à 50 grammes, et le prix affiché cache beaucoup de choses. Une boîte de 20 grammes à 15 $ coûte plus cher au gramme qu'une boîte de 40 grammes à 19 $ : la façon équitable de comparer est donc le prix de la même quantité standard de 30 g.",
  "gd.matcha-under-20.intro.1": "Tout ce qui figure ici est une poudre de matcha nature à 20 $ ou moins, en format de 20 grammes ou plus. Les poudres moins chères sont plus souvent de qualité culinaire ou standard, adaptées aux lattes et à la pâtisserie ; pour le boire à l'eau, cherchez une étiquette cérémonielle et une origine indiquée.",
  "gd.matcha-under-20.list.0.h": "Marques connues avec du matcha à moins de 20 $",
  "gd.matcha-under-20.list.0.n": "D'abord un produit par marque, par ordre de notoriété.",
  "gd.matcha-under-20.list.1.h": "Le plus de grammes pour l'argent",
  "gd.matcha-under-20.list.1.n": "Prix les plus bas aux 30 g sous 20 $, deux au maximum par marque.",
  "gd.matcha-under-20.faq.0.q": "Le matcha à moins de 20 $ est-il bon ?",
  "gd.matcha-under-20.faq.0.a": "Cela peut l'être. Parmi les {n} poudres à moins de 20 $ ici, la médiane est de {median} les 30 g. Prix et qualité sont liés sans être indissociables, et beaucoup de poudres moins chères sont étiquetées qualité culinaire ou standard. Nous listons ce que les marques indiquent plutôt que de classer le goût.",
  "gd.matcha-under-20.faq.1.q": "Combien de matcha obtient-on pour 20 $ ?",
  "gd.matcha-under-20.faq.1.a": "Au prix médian aux 30 g de cette page, 20 $ achètent environ {g} grammes, et les poudres les moins chères vont plus loin.",
  "gd.matcha-under-20.faq.1.none": "Cela dépend de la marque ; comparez le prix aux 30 g.",
  "gd.matcha-under-20.faq.2.q": "Pourquoi voit-on des minimums de 20 grammes ?",
  "gd.matcha-under-20.faq.2.a": "Les échantillons et les minuscules sachets rendent trompeur un prix pour un format standard ; les guides n'incluent donc que des produits vendus en formats d'au moins 20 grammes avec un prix vérifié.",
  "gd.organic-matcha.title": "Matcha bio : marques et prix comparés",
  "gd.organic-matcha.h1": "Matcha bio",
  "gd.organic-matcha.desc": "Poudres de matcha indiquées comme bio certifié, comparées par marque, qualité et prix aux 30 g, le statut bio étant tiré de chaque page produit.",
  "gd.organic-matcha.intro.0": "Le matcha bio est un matcha que le vendeur indique comme bio certifié, le plus souvent selon un système bio USDA ou JAS japonais. Cette page liste des poudres de matcha nature dont la page produit l'indique. Nous enregistrons cette mention ; nous n'avons pas vérifié les certificats.",
  "gd.organic-matcha.intro.1": "Bio certifié décrit la façon dont le thé a été cultivé et transformé, pas son goût ni si un lot particulier a été testé pour les contaminants. Pour ce que dit la recherche publiée sur ce sujet, consultez la page sécurité et contaminants de la bibliothèque de recherche.",
  "gd.organic-matcha.list.0.h": "Marques connues avec du matcha bio",
  "gd.organic-matcha.list.0.n": "D'abord un produit par marque, par ordre de notoriété.",
  "gd.organic-matcha.list.1.h": "Prix le plus bas aux 30 g, bio",
  "gd.organic-matcha.list.1.n": "Deux au maximum par marque.",
  "gd.organic-matcha.faq.0.q": "Le matcha bio coûte-t-il plus cher ?",
  "gd.organic-matcha.faq.0.a": "Ici, la poudre bio médiane coûte {median} les 30 g, contre {all} pour toutes les poudres de matcha comparées sur ce site ({n} bio sur {total}).",
  "gd.organic-matcha.faq.0.none": "Comparez le prix aux 30 g dans le tableau ci-dessus.",
  "gd.organic-matcha.faq.1.q": "Comment savoir si un matcha est vraiment bio ?",
  "gd.organic-matcha.faq.1.a": "Cherchez le logo de certification et l'organisme certificateur indiqués sur la page produit ou l'étiquette. Ce site enregistre la mention bio telle que la marque l'énonce et ne vérifie pas les certificats : consultez la page de la marque avant de vous y fier.",
  "gd.matcha-for-baking-and-cooking.title": "Meilleur matcha pour la pâtisserie et la cuisine : comparé par prix",
  "gd.matcha-for-baking-and-cooking.h1": "Meilleur matcha pour la pâtisserie et la cuisine",
  "gd.matcha-for-baking-and-cooking.desc": "Poudres de matcha que les marques vendent pour la pâtisserie et la cuisine, comparées par qualité, origine et prix aux 30 g.",
  "gd.matcha-for-baking-and-cooking.intro.0": "En pâtisserie et en cuisine, le matcha côtoie le sucre, la matière grasse et la chaleur. Cela estompe la douceur subtile pour laquelle on paie la qualité cérémonielle, c'est pourquoi les recettes demandent généralement une qualité culinaire : une saveur plus forte à moindre coût aux 30 g, souvent en formats plus grands.",
  "gd.matcha-for-baking-and-cooking.intro.1": "Cette page liste des poudres de matcha nature dont la page produit mentionne l'usage culinaire, la pâtisserie, la cuisine ou des recettes, avec la qualité indiquée par chaque marque. Les mélanges aromatisés, les mélanges tout prêts et le matcha vendu en koicha ou usucha sont exclus.",
  "gd.matcha-for-baking-and-cooking.list.0.h": "Marques connues avec du matcha culinaire",
  "gd.matcha-for-baking-and-cooking.list.0.n": "D'abord un produit par marque, par ordre de notoriété.",
  "gd.matcha-for-baking-and-cooking.list.1.h": "Prix le plus bas aux 30 g pour cuisiner",
  "gd.matcha-for-baking-and-cooking.list.1.n": "Deux au maximum par marque.",
  "gd.matcha-for-baking-and-cooking.faq.0.q": "Quel type de matcha est le meilleur pour la pâtisserie ?",
  "gd.matcha-for-baking-and-cooking.faq.0.price": " Les poudres de qualité culinaire ici ont une médiane de {median} les 30 g.",
  "gd.matcha-for-baking-and-cooking.faq.0.a": "La plupart des recettes utilisent une qualité culinaire, moins chère et qui garde sa saveur face au sucre et à la chaleur.{price}",
  "gd.matcha-for-baking-and-cooking.faq.1.q": "La cuisson change-t-elle la couleur du matcha ?",
  "gd.matcha-for-baking-and-cooking.faq.1.a": "Une chaleur prolongée tend à faire virer le vert vif du matcha vers l'olive et à estomper sa saveur, ce qui est une autre raison pour laquelle les pâtissiers se tournent vers des qualités plus fortes et moins chères et ajoutent du matcha généreusement.",
  "gd.how-much-does-matcha-cost.title": "Combien coûte le matcha ? Prix aux 30 g par qualité",
  "gd.how-much-does-matcha-cost.h1": "Combien coûte le matcha ?",
  "gd.how-much-does-matcha-cost.desc": "Prix médian aux 30 g de la poudre de matcha par qualité et région de culture, calculé d'après les pages produits des marques de toute la base de données.",
  "gd.how-much-does-matcha-cost.intro.0": "Les prix du matcha varient énormément : le coût d'une quantité standard de 30 g va de quelques dollars à bien plus de cent. Le prix de la boîte seul est trompeur car les formats vont de 20 grammes à un kilo ; tous les chiffres de cette page sont donc le prix aux 30 g, converti en dollars américains et calculé uniquement d'après les formats indiqués par le vendeur.",
  "gd.how-much-does-matcha-cost.intro.1": "L'écart tient surtout à la qualité, à la récolte et à l'origine. Les tableaux montrent la médiane et la moitié centrale des prix pour chacun, et les listes donnent des exemples dans chaque tranche de prix.",
  "gd.how-much-does-matcha-cost.list.0.h": "Économique : jusqu'à {max} les 30 g",
  "gd.how-much-does-matcha-cost.list.1.h": "Milieu de gamme : de {min} à {max} les 30 g",
  "gd.how-much-does-matcha-cost.list.2.h": "Premium : plus de {min} les 30 g",
  "gd.how-much-does-matcha-cost.method": "Les tranches de prix suivent les niveaux de prix du site, fixés approximativement au tiers et aux deux tiers du prix aux 30 g de l'ensemble du catalogue.",
  "gd.how-much-does-matcha-cost.faq.0.q": "Combien coûte une boîte de matcha de 30 g ?",
  "gd.how-much-does-matcha-cost.faq.0.a": "Sur {n} poudres de matcha de {b} marques, la médiane est de {median} les 30 g, et la moitié centrale des produits se situe entre {lo} et {hi}.",
  "gd.how-much-does-matcha-cost.faq.0.none": "Voir le tableau ci-dessus.",
  "gd.how-much-does-matcha-cost.faq.1.q": "Combien devrait coûter une boîte de matcha ?",
  "gd.how-much-does-matcha-cost.faq.1.a": "Au prix médian, une boîte de 30 grammes coûte environ {t30} et un sachet de 100 grammes environ {t100}. Les qualités cérémonielles coûtent plus et les culinaires moins.",
  "gd.how-much-does-matcha-cost.faq.1.none": "Cela dépend de la qualité et du format.",
  "gd.how-much-does-matcha-cost.faq.2.q": "Pourquoi le matcha est-il cher ?",
  "gd.how-much-does-matcha-cost.faq.2.a": "Le matcha provient de théiers ombragés avant la récolte, cueillis jeunes, cuits à la vapeur, séchés, équeutés et moulus lentement à la meule de pierre ; il demande donc plus de travail que le thé ordinaire, et les qualités supérieures sont faites avec les meilleures feuilles. Les prix indiqués ici sont ceux que pratique chaque marque, pas un verdict sur la valeur.",
  "gd.usucha-vs-koicha-matcha.title": "Matcha usucha vs koicha : quelle différence ?",
  "gd.usucha-vs-koicha-matcha.h1": "Matcha usucha vs koicha",
  "gd.usucha-vs-koicha-matcha.desc": "En quoi l'usucha (léger) et le koicha (épais) diffèrent par la préparation, le goût et le prix aux 30 g, d'après les marques qui étiquettent le matcha selon sa préparation.",
  "gd.usucha-vs-koicha-matcha.intro.0": "L'usucha et le koicha sont deux façons de préparer le matcha dans la cérémonie du thé. L'usucha, ou thé léger, est fouetté avec plus d'eau pour obtenir un bol mousseux. Le koicha, ou thé épais, utilise environ deux fois plus de poudre dans bien moins d'eau et se malaxe, sans fouetter, en un thé épais, presque sirupeux.",
  "gd.usucha-vs-koicha-matcha.intro.1": "Certains vendeurs japonais étiquettent le matcha selon la préparation à laquelle il est destiné. Le matcha étiqueté koicha est souvent fait de feuilles plus fines et plus sucré, moins astringent, car le thé épais ne peut pas cacher l'amertume. Cette qualité se voit dans le prix.",
  "gd.usucha-vs-koicha-matcha.list.0.h": "Matcha usucha",
  "gd.usucha-vs-koicha-matcha.list.1.h": "Matcha koicha",
  "gd.usucha-vs-koicha-matcha.faq.0.q": "Quelle est la différence entre l'usucha et le koicha ?",
  "gd.usucha-vs-koicha-matcha.faq.0.price": " Dans ces données, le matcha étiqueté usucha a une médiane de {um} les 30 g et le koicha de {km}.",
  "gd.usucha-vs-koicha-matcha.faq.0.a": "L'usucha est un thé léger fouetté ; le koicha est un thé épais fait avec environ deux fois plus de poudre dans bien moins d'eau.{price}",
  "gd.usucha-vs-koicha-matcha.faq.1.q": "Puis-je faire de l'usucha avec du matcha koicha ?",
  "gd.usucha-vs-koicha-matcha.faq.1.a": "Oui. Le matcha étiqueté koicha est plus sucré et plus doux, il convient donc aussi en léger ; il coûte simplement plus cher par bol.",
  "gd.usucha-vs-koicha-matcha.faq.2.q": "Puis-je faire du koicha avec du matcha usucha ?",
  "gd.usucha-vs-koicha-matcha.faq.2.a": "On peut, mais davantage d'amertume et d'astringence ressortent quand le thé est épais, et c'est justement pourquoi du matcha est étiqueté koicha.",
  "wc.title": "Qu'est-ce que le matcha cérémoniel ? Origine et sens",
  "wc.desc": "D'où vient le terme matcha de « qualité cérémonielle », quel est son rapport avec la cérémonie japonaise du thé, ce qu'il garantit ou non aujourd'hui, et ce que montrent nos données de prix.",
  "wc.short.h": "La réponse courte",
  "wc.short.p": "« Qualité cérémonielle » est une étiquette en anglais pour le matcha fait pour être fouetté à l'eau et bu seul. Ce n'est pas une qualité japonaise et aucun organisme public ou professionnel ne la définit. La cérémonie du thé dont elle emprunte le nom est bien réelle et vieille de plusieurs siècles. L'étiquette est un raccourci bien plus tardif du commerce d'exportation, et elle signifie ce que le vendeur veut qu'elle signifie.",
  "wc.ceremony.h": "La cérémonie derrière le mot",
  "wc.ceremony.p": "Le mot « cérémoniel » renvoie à la cérémonie japonaise du thé, appelée chanoyu ou sadō, où un hôte prépare et sert le matcha à ses invités. Le matcha et la cérémonie se sont développés ensemble pendant environ quatre siècles :",
  "wc.tl.0.when": "Vers 1191",
  "wc.tl.0.what": "Le moine zen Eisai revient de Chine avec la façon de préparer le thé en poudre de la dynastie Song : de la feuille moulue fouettée dans de l'eau chaude. Eisai écrit le Kissa Yōjōki (« Boire du thé pour la santé »), qu'il présente au shogun Minamoto no Sanetomo en 1214. Le thé était alors considéré comme un remède et une aide à la méditation.",
  "wc.tl.1.when": "XIIIe siècle",
  "wc.tl.1.what": "Myōe, disciple d'Eisai, plante du thé à Togano'o et à Uji, près de Kyoto. Uji devient la région théicole la plus prestigieuse du Japon, une réputation qu'elle garde encore.",
  "wc.tl.2.when": "XIVe siècle",
  "wc.tl.2.what": "Des meules de pierre conçues pour le thé apparaissent et produisent une poudre plus fine que les anciens broyeurs.",
  "wc.tl.3.when": "XVe et XVIe siècles",
  "wc.tl.3.what": "Les producteurs d'Uji se mettent à couvrir les théiers avant la récolte. La pratique était longtemps datée de la fin du XVIe siècle, mais l'analyse des sols des plantations d'Uji suggère qu'elle a commencé dès la première moitié du XVe siècle. L'ombrage rend la feuille d'un vert profond et accroît l'umami ; la feuille préparée pour la mouture s'appelle le tencha. Auparavant, le thé en poudre était brunâtre.",
  "wc.tl.4.when": "XVIe siècle",
  "wc.tl.4.what": "Des maîtres de thé comme Murata Jukō et Sen no Rikyū préfèrent la simplicité à l'ostentation. Leur approche devient le chanoyu, sadō ou chadō : la cérémonie japonaise du thé, bâtie autour de la préparation et du service du matcha.",
  "wc.tl.5.when": "Période d'Edo (1603 à 1867)",
  "wc.tl.5.what": "Les maîtres de thé officiels d'Uji détiennent les droits exclusifs sur la culture à l'ombre et le matcha de haute qualité, et fournissent le shogun et la cour. Le plus ancien nom de marque de matcha connu, Baba Mukashi, date de ce monde.",
  "wc.tl.6.when": "Après la période d'Edo",
  "wc.tl.6.what": "Les privilèges d'Uji prennent fin et la culture à l'ombre gagne d'autres régions du Japon. La cérémonie du thé se poursuit au sein d'écoles comme l'Urasenke et l'Omotesenke.",
  "wc.tl.7.when": "Fin du XXe siècle et XXIe siècle",
  "wc.tl.7.what": "Le matcha devient un produit mondial, vendu comme boisson et comme ingrédient alimentaire. Les vendeurs ont besoin de mots en anglais pour la différence. « Cérémoniel » et « culinaire » sont ceux qui s'imposent.",
  "wc.trade.h": "Comment la filière japonaise nomme réellement les choses",
  "wc.trade.p1": "Les maisons de thé japonaises ne classent pas le matcha en « cérémoniel » et « culinaire ». Leur vocabulaire est plus précis. La matière première est le tencha, la feuille ombragée avant d'être moulue. Dans la cérémonie du thé, il y a deux préparations, le koicha (thé épais, un peu de poudre dans peu d'eau) et l'usucha (thé léger, fouetté en mousse), et beaucoup de maisons font des gammes distinctes pour chacune. Les gammes portent des noms traditionnels plutôt que des qualités. Les noms en -mukashi (« autrefois ») sont le schéma classique, qui remonte au moins à Baba Mukashi, le plus ancien nom de marque de matcha connu.",
  "wc.trade.p2": "Le schéma est bien vivant dans la base de données : {n} produits de {b} marques portent un nom en mukashi. Les marques de la base étiquettent aussi {koi} poudres nature comme koicha et {usu} comme usucha. Ces mots décrivent la façon dont le thé est destiné à être préparé, plutôt que de le classer comme semble le faire « qualité cérémonielle ».",
  "wc.how.h": "Comment est apparue la « qualité cérémonielle »",
  "wc.how.p1": "Quand le matcha a commencé à se vendre à l'étranger, les vendeurs ont eu besoin d'un moyen rapide de dire à l'acheteur quelle poudre fouetter à l'eau et laquelle mettre dans un latte ou un gâteau. L'anglais a fourni deux mots : « cérémoniel » pour la première et « culinaire » pour la seconde. Un fournisseur de thé japonais décrit la traduction ainsi : les gammes destinées au koicha et à l'usucha sont devenues « cérémoniel », et tout le reste est devenu « culinaire ».",
  "wc.how.p2": "Nous n'avons trouvé ni premier emploi documenté de l'expression ni entreprise unique qui l'aurait inventée, et nous n'en revendiquons donc aucune. Ce sur quoi s'accordent les vendeurs de la filière, y compris certains qui utilisent l'étiquette, c'est qu'elle n'a jamais été une classification japonaise et n'a pas de définition légale. Le matcha en tant que produit est défini par des normes et par les consignes japonaises d'étiquetage alimentaire ; à notre connaissance, aucune ne définit un niveau cérémoniel.",
  "wc.today.h": "Ce que cela signifie aujourd'hui",
  "wc.today.1.b": "Une déclaration d'usage prévu.",
  "wc.today.1.t": "Quand une marque qualifie une poudre de cérémonielle, elle dit qu'elle doit être bonne fouettée à l'eau seule, sans lait ni édulcorant pour la couvrir.",
  "wc.today.2.b": "Un signal de prix, pas une garantie de qualité.",
  "wc.today.2.t": "Les poudres cérémonielles coûtent en moyenne plus que les culinaires, mais l'étiquette seule ne dit pas combien de plus ni si cela vaut la peine.",
  "wc.today.3.b": "Auto-attribuée.",
  "wc.today.3.t": "Il n'y a ni organisme de contrôle, ni certificat, ni sanction pour un usage lâche du mot. Deux marques peuvent l'employer pour des matchas très différents.",
  "wc.today.4.b": "Un point de départ pour poser des questions.",
  "wc.today.4.t": "Les détails qui disent vraiment quelque chose sont le cultivar, la récolte, la région de culture, l'ombrage, la mouture et le producteur. Une marque qui les donne vous en dit plus que l'étiquette.",
  "wc.data.h": "Ce que montrent nos données",
  "wc.data.p1": "Nous comparons des poudres de matcha nature avec un prix vérifié et un format d'au moins 20 grammes. Sur {total} poudres de ce type, {n} ({share} %) sont étiquetées cérémonielles par leurs marques.",
  "wc.data.s1": "médiane les 30 g, cérémoniel",
  "wc.data.s2": "médiane les 30 g, culinaire",
  "wc.data.s3": "moitié centrale, cérémoniel",
  "wc.data.s4": "fourchette complète, cérémoniel",
  "wc.data.p2": "La dispersion est le point clé. Sur l'ensemble des poudres de matcha de la base, la médiane est de {median} les 30 g, et l'étiquette cérémonielle couvre tout, des boîtes les moins chères aux plus chères. Sur les pages des marques elles-mêmes, {withRegion} % des poudres cérémonielles nomment une région de culture et {withCultivar} % un cultivar : l'étiquette est donc ce qu'il y a de moins informatif à leur sujet. C'est pourquoi nous comparons ces détails à la place.",
  "wc.read.h": "Lire l'étiquette avec discernement",
  "wc.read.1": "Considérez « cérémoniel » comme la marque vous disant à quoi sert la poudre, et cherchez les faits qui la sous-tendent.",
  "wc.read.2": "Vérifiez si la marque nomme une région et un cultivar, et quand la récolte a eu lieu.",
  "wc.read.3": "Comparez le prix aux 30 g, pas le prix de la boîte. Notre {link} montre les fourchettes habituelles.",
  "wc.read.3.link": "guide des coûts",
  "wc.read.4": "Si vous voulez le cadre traditionnel, cherchez les gammes koicha et usucha des maisons de thé japonaises ; voir {link}.",
  "wc.read.4.link": "usucha vs koicha",
  "wc.faq.0.q": "Le matcha de qualité cérémonielle est-il utilisé dans la cérémonie japonaise du thé ?",
  "wc.faq.0.a": "Pas forcément. Les maisons de thé japonaises vendent du matcha en gammes conçues pour le koicha (thé épais) et l'usucha (thé léger), souvent sous des noms traditionnels, ce qui est l'équivalent le plus proche au Japon. « Qualité cérémonielle » sur un produit d'exportation est une étiquette en anglais sans lien fixe avec l'une d'elles.",
  "wc.faq.1.q": "Qui décide de ce qui compte comme qualité cérémonielle ?",
  "wc.faq.1.a": "Chaque marque décide. À notre connaissance, aucune norme japonaise ou internationale ne définit le terme, et personne ne l'audite. Plusieurs vendeurs de thé disent la même chose dans leurs propres explications de l'étiquette.",
  "wc.faq.2.q": "Le matcha cérémoniel est-il toujours de la meilleure qualité ?",
  "wc.faq.2.a": "Non. L'étiquette ne fixe ni plancher ni plafond. Dans nos données, les poudres étiquetées cérémonielles vont de {min} à {max} les 30 g, avec la moitié centrale entre {lo} et {hi}.",
  "wc.faq.3.q": "Puis-je utiliser du matcha cérémoniel pour des lattes ou de la pâtisserie ?",
  "wc.faq.3.a": "Oui, rien ne l'empêche, mais le lait, le sucre et la chaleur cachent une bonne part de ce pour quoi la qualité cérémonielle est payée. Notre guide matcha cérémoniel contre culinaire compare les deux par prix et par usage.",
  "wc.src.h": "Sources et notes",
  "wc.src.p": "L'histoire résume des récits publiés, principalement l'historique cité sur Wikipédia, et les dates de l'ombrage et du monopole de l'époque d'Edo en proviennent. Les détails diffèrent selon les sources ; nous indiquons donc les dates avec prudence. Les commentaires sur l'étiquette viennent des explications de vendeurs de thé eux-mêmes, dont plusieurs vendent du matcha, ce qu'il faut garder à l'esprit. Les chiffres ci-dessus proviennent de la table de produits de MatchaDB et sont actualisés à chaque reconstruction du site.",
  "wc.related": "À lire aussi : {a}, {b}, {c}.",
  "wc.related.a": "matcha cérémoniel vs culinaire",
  "mp.farm.farm-hattori-kikugawa": "Une ferme familiale de quatrième génération, à domaine unique, à Kikugawa, dans la préfecture de Shizuoka, dirigée par M. Hattori.",
  "mp.farm.farm-isagawa-tenryu": "Une plantation biologique de montagne isolée de 20 hectares, à 300-600 m d'altitude, dans la sous-région de Haruno, à Tenryū, préfecture de Shizuoka.",
  // @@END
};

